const fs = require('fs');
const { EdgeTTS } = require('edge-tts-universal');

async function main() {
  // Parse command-line arguments
  const inputFile = process.argv.find(arg => arg === '--input')
    ? process.argv[process.argv.indexOf('--input') + 1]
    : 'output/script.txt';
  const outputFile = process.argv.find(arg => arg === '--output')
    ? process.argv[process.argv.indexOf('--output') + 1]
    : 'output/voiceover.mp3';

  // Read the script generated by Groq
  const scriptText = fs.readFileSync(inputFile, 'utf-8');
  const voiceName = 'en-US-JennyNeural';

  console.log(`🎙️ Generating voiceover for: "${scriptText.substring(0, 60)}..."`);

  // Create TTS instance and set voice
  const tts = new EdgeTTS();
  await tts.setVoice(voiceName);
  
  // Synthesize the text
  const result = await tts.synthesize(scriptText);

  // Write audio to file (result.audio is an ArrayBuffer)
  const audioBuffer = Buffer.from(result.audio);
  fs.writeFileSync(outputFile, audioBuffer);

  console.log(`✅ Voiceover saved to ${outputFile}`);
}

main().catch(err => {
  console.error('❌ Voiceover generation failed:', err);
  process.exit(1);
});
